//! IPA, checked against the whole hand-authored lexicon.
//!
//! Every `ipa` field in `data/lexicon/lexicon.json` is generated by the
//! TypeScript engine (tests/lexiconIpa.test.ts asserts it), so the lexicon is
//! 301 pinned cases: if Rust transcribes any entry differently, the two
//! engines disagree about how the language sounds.
//!
//! That makes this a stronger gate than a hand-written fixture would be — it
//! covers every spelling pattern the language actually uses, including the
//! stress exceptions and the written variants.

use gkh_core::data::lexicon::ENTRIES;
use gkh_core::phonology::{ipa_of_sentence, ipa_of_word, stressed_syllable_index, syllabify, try_tokenize_word};

#[test]
fn transcribes_every_lexicon_entry_exactly_as_typescript_does() {
    let mut drifted: Vec<String> = Vec::new();

    for entry in ENTRIES {
        // Hyphenated compounds are written as one phonological word.
        let bare = entry.gkh.replace('-', "");
        let actual = ipa_of_word(&bare);
        if actual != entry.ipa {
            drifted.push(format!("{} {:?}: expected {:?}, got {:?}", entry.id, entry.gkh, entry.ipa, actual));
        }
    }

    assert!(
        drifted.is_empty(),
        "Rust and TypeScript disagree on the pronunciation of {} of {} entries:\n  {}",
        drifted.len(),
        ENTRIES.len(),
        drifted.iter().take(10).cloned().collect::<Vec<_>>().join("\n  ")
    );
}

#[test]
fn the_lexicon_is_a_substantial_fixture() {
    assert!(ENTRIES.len() >= 300);
}

#[test]
fn stress_is_penultimate_by_default() {
    // ghûldor: ghûl-dor, two syllables, stress on the first.
    let tokens = try_tokenize_word("ghûldor").unwrap();
    let syllables = syllabify(&tokens);
    assert_eq!(syllables.len(), 2);
    assert_eq!(stressed_syllable_index(&syllables), Some(0));
    assert!(ipa_of_word("ghûldor").starts_with('ˈ'));
}

#[test]
fn stress_shifts_to_a_long_final_syllable() {
    // khardûm: the final syllable has a long vowel, so it takes the stress.
    let tokens = try_tokenize_word("khardûm").unwrap();
    let syllables = syllabify(&tokens);
    assert_eq!(stressed_syllable_index(&syllables), Some(syllables.len() - 1));
    assert_eq!(ipa_of_word("khardûm"), "xaʀˈduːm");
}

#[test]
fn a_monosyllable_stresses_its_only_syllable() {
    assert_eq!(ipa_of_word("khar"), "ˈxaʀ");
}

#[test]
fn an_unknown_word_transcribes_to_nothing_rather_than_something_invented() {
    assert_eq!(ipa_of_word("xyzzyq"), "");
}

#[test]
fn a_sentence_is_transcribed_word_by_word() {
    assert_eq!(ipa_of_sentence("ük selu dor"), "/ˈuːk/ /ˈsɛlʊ/ /ˈdɔʀ/");
}
